<?php $rows=$pdo->query('SELECT p.*,m.npm,m.nama,s.tanggal,mk.nama_mk FROM pengajuan_absensi p JOIN mahasiswa m ON m.id=p.mahasiswa_id JOIN sesi_absensi s ON s.id=p.sesi_id JOIN jadwal j ON j.id=s.jadwal_id JOIN mata_kuliah mk ON mk.id=j.mata_kuliah_id ORDER BY p.created_at DESC')->fetchAll();?><section class="section"><table class="table"><thead><tr><th>Mahasiswa</th><th>Sesi</th><th>Jenis</th><th>Alasan</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['nama'])?><small style="display:block;color:#887d90"><?=e($r['npm'])?></small></td><td><?=e($r['tanggal'].' · '.$r['nama_mk'])?></td><td><?=e($r['jenis'])?></td><td><?=e($r['alasan'])?></td><td><span class="badge"><?=e($r['status'])?></span></td></tr><?php endforeach;?></tbody></table></section>
</main></div><?php require __DIR__.'/../partials/footer.php'; ?>